598	
599	  interface PluginBridgeErrorResponse {
600	    code: PluginBridgeErrorCode;
601	    message: string;
602	    details?: unknown;
603	  }
604	
605	  function mapRpcErrorToBridgeError(err: unknown): PluginBridgeErrorResponse {
606	    if (err instanceof JsonRpcCallError) {
607	      switch (err.code) {
608	        case PLUGIN_RPC_ERROR_CODES.WORKER_UNAVAILABLE:
609	          return { code: "WORKER_UNAVAILABLE", message: err.message, details: err.data };
610	        case PLUGIN_RPC_ERROR_CODES.CAPABILITY_DENIED:
611	          return { code: "CAPABILITY_DENIED", message: err.message, details: err.data };
612	        case PLUGIN_RPC_ERROR_CODES.TIMEOUT:
613	          return { code: "TIMEOUT", message: err.message, details: err.data };
614	        case PLUGIN_RPC_ERROR_CODES.WORKER_ERROR:
615	          return { code: "WORKER_ERROR", message: err.message, details: err.data };
616	        default:
617	          return { code: "UNKNOWN", message: err.message, details: err.data };
618	      }
619	    }
620	
621	    const message = err instanceof Error ? err.message : String(err);
622	
623	    if (message.includes("not running") || message.includes("not registered")) {
624	      return { code: "WORKER_UNAVAILABLE", message };
625	    }
626	
627	    return { code: "UNKNOWN", message };
628	  }
