634	  async function validateToolRunContextScope(runContext: ToolRunContext): Promise<string | null> {
635	    const [agent] = await db
636	      .select({ companyId: agents.companyId })
637	      .from(agents)
638	      .where(eq(agents.id, runContext.agentId))
639	      .limit(1);
640	    if (!agent || agent.companyId !== runContext.companyId) {
641	      return '"runContext.agentId" does not belong to "runContext.companyId"';
642	    }
643	
644	    const [run] = await db
645	      .select({ companyId: heartbeatRuns.companyId, agentId: heartbeatRuns.agentId })
646	      .from(heartbeatRuns)
647	      .where(eq(heartbeatRuns.id, runContext.runId))
648	      .limit(1);
649	    if (!run || run.companyId !== runContext.companyId) {
650	      return '"runContext.runId" does not belong to "runContext.companyId"';
651	    }
652	    if (run.agentId !== runContext.agentId) {
653	      return '"runContext.runId" does not belong to "runContext.agentId"';
654	    }
655	
656	    const [project] = await db
657	      .select({ companyId: projects.companyId })
658	      .from(projects)
659	      .where(eq(projects.id, runContext.projectId))
660	      .limit(1);
661	    if (!project || project.companyId !== runContext.companyId) {
662	      return '"runContext.projectId" does not belong to "runContext.companyId"';
663	    }
664	
665	    return null;
666	  }
