1536	  /**
1537	   * POST /api/plugins/:pluginId/webhooks/:endpointKey
1538	   *
1539	   * NOTE: This route does NOT require board authentication — webhook endpoints
1540	   * must be publicly accessible for external callers.
1541	   */
1542	  const receiveWebhook: Handler = async (ctx) => {
1543	    if (!webhookDeps) {
1544	      return Response.json({ error: "Webhook ingestion is not enabled" }, { status: 501 });
1545	    }
1546	
1547	    const pluginId = ctx.param("pluginId");
1548	    const endpointKey = ctx.param("endpointKey");
1549	    if (!pluginId) return Response.json({ error: "Missing pluginId" }, { status: 400 });
1550	    if (!endpointKey) return Response.json({ error: "Missing endpointKey" }, { status: 400 });
1551	
1552	    const plugin = await resolvePlugin(registry, pluginId);
1553	    if (!plugin) {
1554	      return Response.json({ error: "Plugin not found" }, { status: 404 });
1555	    }
1556	
1557	    if (plugin.status !== "ready") {
1558	      return Response.json({
1559	        error: `Plugin is not ready (current status: ${plugin.status})`,
1560	      }, { status: 400 });
1561	    }
1562	
1563	    const manifest = plugin.manifestJson;
1564	    if (!manifest) {
1565	      return Response.json({ error: "Plugin manifest is missing" }, { status: 400 });
1566	    }
1567	
1568	    const capabilities = manifest.capabilities ?? [];
1569	    if (!capabilities.includes("webhooks.receive")) {
1570	      return Response.json({
1571	        error: "Plugin does not have the webhooks.receive capability",
1572	      }, { status: 400 });
1573	    }
1574	
1575	    const declaredWebhooks = manifest.webhooks ?? [];
1576	    const webhookDecl = declaredWebhooks.find((w) => w.endpointKey === endpointKey);
1577	    if (!webhookDecl) {
1578	      return Response.json({
1579	        error: `Webhook endpoint '${endpointKey}' is not declared by this plugin`,
1580	      }, { status: 404 });
1581	    }
1582	
1583	    const requestId = randomUUID();
1584	    const rawHeaders: Record<string, string> = {};
1585	    ctx.headers.forEach((value, name) => {
1586	      rawHeaders[name] = value;
1587	    });
1588	
1589	    // The rawBody stash from express.json() verify callback is not available in
1590	    // the transport-agnostic ctx. Fall back to re-reading via ctx.text().
1591	    const rawBody = await ctx.text();
1592	    const parsedBody = await ctx.json<unknown>().catch(() => null);
1593	    const payload = (parsedBody as Record<string, unknown> | undefined) ?? {};
1594	
1595	    const startedAt = new Date();
1596	    const [delivery] = await db
1597	      .insert(pluginWebhookDeliveries)
1598	      .values({
1599	        pluginId: plugin.id,
1600	        webhookKey: endpointKey,
1601	        status: "pending",
1602	        payload,
1603	        headers: rawHeaders,
1604	        startedAt,
1605	      })
1606	      .returning({ id: pluginWebhookDeliveries.id });
1607	
1608	    try {
1609	      await webhookDeps.workerManager.call(plugin.id, "handleWebhook", {
1610	        endpointKey,
1611	        headers: rawHeaders,
1612	        rawBody,
1613	        parsedBody,
1614	        requestId,
1615	      });
1616	
1617	      const finishedAt = new Date();
1618	      const durationMs = finishedAt.getTime() - startedAt.getTime();
1619	      await db
1620	        .update(pluginWebhookDeliveries)
1621	        .set({ status: "success", durationMs, finishedAt })
1622	        .where(eq(pluginWebhookDeliveries.id, delivery.id));
1623	
1624	      return Response.json({ deliveryId: delivery.id, status: "success" }, { status: 200 });
1625	    } catch (err) {
1626	      const finishedAt = new Date();
1627	      const durationMs = finishedAt.getTime() - startedAt.getTime();
1628	      const errorMessage = err instanceof Error ? err.message : String(err);
1629	
1630	      await db
1631	        .update(pluginWebhookDeliveries)
1632	        .set({ status: "failed", durationMs, error: errorMessage, finishedAt })
1633	        .where(eq(pluginWebhookDeliveries.id, delivery.id));
1634	
1635	      return Response.json({ deliveryId: delivery.id, status: "failed", error: errorMessage }, { status: 502 });
1636	    }
1637	  };
