1874	    if (!bridgeDeps?.streamBus) {
1875	      res.status(501).json({ error: "Plugin stream bridge is not enabled" });
1876	      return;
1877	    }
1878	
1879	    const { pluginId, channel } = req.params;
1880	    const companyId = req.query.companyId as string | undefined;
1881	
1882	    if (!companyId) {
1883	      res.status(400).json({ error: '"companyId" query parameter is required' });
1884	      return;
1885	    }
1886	
1887	    const plugin = await resolvePlugin(registry, pluginId);
1888	    if (!plugin) {
1889	      res.status(404).json({ error: "Plugin not found" });
1890	      return;
1891	    }
1892	
1893	    assertCompanyAccess(req, companyId);
1894	
1895	    res.writeHead(200, {
1896	      "Content-Type": "text/event-stream",
1897	      "Cache-Control": "no-cache",
1898	      "Connection": "keep-alive",
1899	      "X-Accel-Buffering": "no",
1900	    });
1901	    res.flushHeaders();
1902	
1903	    res.write(":ok\n\n");
1904	
1905	    let unsubscribed = false;
1906	    const safeUnsubscribe = () => {
1907	      if (!unsubscribed) {
1908	        unsubscribed = true;
1909	        unsubscribe();
1910	      }
1911	    };
1912	
1913	    const unsubscribe = bridgeDeps.streamBus.subscribe(
1914	      plugin.id,
1915	      channel,
1916	      companyId,
1917	      (event, eventType) => {
1918	        if (unsubscribed || !res.writable) return;
1919	        try {
1920	          if (eventType !== "message") {
1921	            res.write(`event: ${eventType}\n`);
1922	          }
1923	          res.write(`data: ${JSON.stringify(event)}\n\n`);
1924	        } catch {
1925	          safeUnsubscribe();
1926	        }
1927	      },
1928	    );
1929	
1930	    req.on("close", safeUnsubscribe);
