1943	  router.use("/plugins/:pluginId/api", async (req, res) => {
1944	    if (!bridgeDeps) {
1945	      res.status(501).json({ error: "Plugin scoped API routes are not enabled" });
1946	      return;
1947	    }
1948	
1949	    const { pluginId } = req.params;
1950	    const plugin = await resolvePlugin(registry, pluginId);
1951	    if (!plugin) {
1952	      res.status(404).json({ error: "Plugin not found" });
1953	      return;
1954	    }
1955	    if (plugin.status !== "ready") {
1956	      res.status(503).json({ error: `Plugin is not ready (current status: ${plugin.status})` });
1957	      return;
1958	    }
1959	    const isWorkerRunning = typeof bridgeDeps.workerManager.isRunning === "function"
1960	      ? bridgeDeps.workerManager.isRunning(plugin.id)
1961	      : true;
1962	    if (!isWorkerRunning) {
1963	      res.status(503).json({ error: "Plugin worker is not running" });
1964	      return;
1965	    }
1966	    if (!plugin.manifestJson.capabilities.includes("api.routes.register")) {
1967	      res.status(404).json({ error: "Plugin does not expose scoped API routes" });
1968	      return;
1969	    }
1970	
1971	    const requestPath = req.path || "/";
1972	    const routes = plugin.manifestJson.apiRoutes ?? [];
1973	    const match = routes
1974	      .map((route) => ({ route, params: matchScopedApiRoute(route, req.method, requestPath) }))
1975	      .find((candidate) => candidate.params !== null);
1976	    if (!match || !match.params) {
1977	      res.status(404).json({ error: "Plugin API route not found" });
1978	      return;
1979	    }
1980	
1981	    try {
1982	      assertScopedApiAuth(req, match.route);
1983	      const companyId = await resolveScopedApiCompanyId(match.route, match.params, req);
1984	      if (!companyId) {
1985	        res.status(400).json({ error: "Unable to resolve company for plugin API route" });
1986	        return;
1987	      }
1988	      assertCompanyAccess(req, companyId);
1989	      await enforceScopedApiCheckout(req, match.route, match.params, companyId);
1990	      if (req.method !== "GET" && req.headers["content-type"] && !req.is("application/json")) {
1991	        res.status(415).json({ error: "Plugin API routes accept JSON requests only" });
1992	        return;
1993	      }
1994	      const requestBody = req.body ?? null;
1995	      const bodySize = Buffer.byteLength(JSON.stringify(requestBody));
1996	      if (bodySize > PLUGIN_API_BODY_LIMIT_BYTES) {
1997	        res.status(413).json({ error: "Plugin API request body is too large" });
1998	        return;
1999	      }
2000	
2001	      const actor = getActorInfo(req);
2002	      const input: PluginScopedApiRequest = {
2003	        routeKey: match.route.routeKey,
2004	        method: req.method,
2005	        path: requestPath,
2006	        params: match.params,
2007	        query: normalizeQuery(req.query),
2008	        body: requestBody,
2009	        actor: {
2010	          actorType: actor.actorType,
2011	          actorId: actor.actorId,
2012	          agentId: actor.agentId,
2013	          userId: actor.actorType === "user" ? actor.actorId : null,
2014	          runId: actor.runId,
2015	        },
2016	        companyId,
2017	        headers: sanitizePluginRequestHeaders(req),
2018	      };
2019	
2020	      const result = await bridgeDeps.workerManager.call(
2021	        plugin.id,
2022	        "handleApiRequest",
2023	        input,
2024	      ) as PluginScopedApiResponse;
2025	      const status = Number.isInteger(result.status) && Number(result.status) >= 200 && Number(result.status) <= 599
2026	        ? Number(result.status)
2027	        : 200;
2028	      applyPluginScopedApiResponseHeaders(res, result.headers);
